export const DashboardSchema = z.object({ "widgets": z.array(z.union([z.object({ "id": z.string(), "title": z.string(), "dataset_id": z.string(), "description": z.string().default(""), "type": z.literal("metric"), "field": z.string().default("value"), "aggregation": z.enum(["sum","count","avg"]).default("sum") }).strict(), z.object({ "id": z.string(), "title": z.string(), "dataset_id": z.string(), "description": z.string().default(""), "type": z.enum(["bar_chart","line_chart","area_chart","donut_chart"]), "x_field": z.string().default("label"), "y_field": z.string().default("value"), "sort": z.union([z.enum(["ascending","descending"]), z.null()]).default(null) }).strict(), z.object({ "id": z.string(), "title": z.string(), "dataset_id": z.string(), "description": z.string().default(""), "type": z.literal("table"), "columns": z.array(z.string()).default([]) }).strict(), z.object({ "id": z.string(), "title": z.string(), "dataset_id": z.string(), "description": z.string().default(""), "type": z.literal("map_choropleth"), "x_field": z.string().default("key"), "y_field": z.string().default("value") }).strict()])).default([]), "layouts": z.record(z.array(z.object({ "i": z.string(), "x": z.number().int().gte(0), "y": z.number().int().gte(0), "w": z.number().int().gte(1).lte(12), "h": z.number().int().gte(1).lte(30) }).strict())).default({}), "pinned_widget_ids": z.array(z.string()).default([]) }).strict();
export type Dashboard = z.infer<typeof DashboardSchema>;

export const HealthSchema = z.object({ "status": z.literal("ok").default("ok"), "data_available": z.boolean(), "llm_configured": z.boolean(), "model": z.union([z.string(), z.null()]).default(null) }).strict();
export type Health = z.infer<typeof HealthSchema>;

export const StageSchema = z.object({ "run_id": z.string(), "stage": z.string(), "label": z.string() }).strict();
export type Stage = z.infer<typeof StageSchema>;

export const ErrorSchema = z.object({ "run_id": z.string(), "code": z.string(), "message": z.string() }).strict();
export type Error = z.infer<typeof ErrorSchema>;

export type Widget = Dashboard["widgets"][number];
export type Filters = NonNullable<ChatRequest["filters"]>;
